87	        StringBuilder sb = new StringBuilder();
88	        for (int i = 0; i < points.size(); i++) {
89	            if (i > 0) {
90	                sb.append(';');
91	            }
92	            sb.append(points.get(i).x()).append(',').append(points.get(i).y());
93	        }
94	        return sb.toString();
95	    }
